                    {
                        id: 1,
                        attributes: {
                            thumbnailImgUrl: 'https://presentations-slides-prod.s3.amazonaws.com/22527844/46499273/2022/11/09/f29da73ff4ac251b2b1560bd264f63f3.thumb.jpg',
